// Probe helper: run the reference Python executable over a JSON corpus and show
// its exact output. Lets discovery agents study behaviour without fighting shell
// quoting.
//
// Usage:  node /workspace/harness/probe.mjs <corpus.json>
//         node /workspace/harness/probe.mjs --inline '["SELECT 1; SELECT 2"]'
//
// Entries are either a string (argv becomes ["--a", s]) or an array of raw argv.

import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test2_executable';
const args = process.argv.slice(2);

let entries;
if (args[0] === '--inline') entries = JSON.parse(args[1]);
else entries = JSON.parse(readFileSync(args[0], 'utf8'));

for (const entry of entries) {
  const argv = Array.isArray(entry) ? entry.map(String) : ['--a', String(entry)];
  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 });
  console.log('IN   : ' + JSON.stringify(argv));
  console.log('OUT  : ' + JSON.stringify(r.stdout ?? ''));
  if (r.stderr) console.log('ERR  : ' + JSON.stringify(r.stderr));
  console.log('CODE : ' + r.status);
  console.log('');
}
